-- Verify: every count 0
SELECT 'dual_meet_matches fall' AS what, count(*) FROM dual_meet_matches WHERE result_type::text IN ('Fall') AND fall_time_seconds < 3
UNION ALL SELECT 'dual_meet_matches tf' AS what, count(*) FROM dual_meet_matches WHERE result_type::text IN ('TF') AND (fall_time_seconds < 13 OR fall_time_seconds IS NULL)
UNION ALL SELECT 'dual_meet_matches inj' AS what, count(*) FROM dual_meet_matches WHERE result_type::text IN ('Inj.') AND (fall_time_seconds < 3 OR fall_time_seconds IS NULL)
UNION ALL SELECT 'dual_meet_matches_girls fall' AS what, count(*) FROM dual_meet_matches_girls WHERE result_type::text IN ('Fall') AND fall_time_seconds < 3
UNION ALL SELECT 'dual_meet_matches_girls tf' AS what, count(*) FROM dual_meet_matches_girls WHERE result_type::text IN ('TF') AND (fall_time_seconds < 13 OR fall_time_seconds IS NULL)
UNION ALL SELECT 'dual_meet_matches_girls inj' AS what, count(*) FROM dual_meet_matches_girls WHERE result_type::text IN ('Inj.') AND (fall_time_seconds < 3 OR fall_time_seconds IS NULL)
UNION ALL SELECT 'tournament_bouts fall' AS what, count(*) FROM tournament_bouts WHERE result_type::text IN ('Fall') AND fall_time_seconds < 3
UNION ALL SELECT 'tournament_bouts tf' AS what, count(*) FROM tournament_bouts WHERE result_type::text IN ('TF') AND (fall_time_seconds < 13 OR fall_time_seconds IS NULL)
UNION ALL SELECT 'tournament_bouts inj' AS what, count(*) FROM tournament_bouts WHERE result_type::text IN ('Inj.') AND (fall_time_seconds < 3 OR fall_time_seconds IS NULL)
UNION ALL SELECT 'tournament_bouts_girls fall' AS what, count(*) FROM tournament_bouts_girls WHERE result_type::text IN ('Fall') AND fall_time_seconds < 3
UNION ALL SELECT 'tournament_bouts_girls tf' AS what, count(*) FROM tournament_bouts_girls WHERE result_type::text IN ('TF') AND (fall_time_seconds < 13 OR fall_time_seconds IS NULL)
UNION ALL SELECT 'tournament_bouts_girls inj' AS what, count(*) FROM tournament_bouts_girls WHERE result_type::text IN ('Inj.') AND (fall_time_seconds < 3 OR fall_time_seconds IS NULL)
UNION ALL SELECT 'matches fall' AS what, count(*) FROM matches WHERE win_type::text IN ('FALL') AND fall_time_seconds < 3
UNION ALL SELECT 'matches tf' AS what, count(*) FROM matches WHERE win_type::text IN ('TF-1.5', 'TF-1') AND (fall_time_seconds < 13 OR fall_time_seconds IS NULL)
UNION ALL SELECT 'matches inj' AS what, count(*) FROM matches WHERE win_type::text IN ('INJ') AND (fall_time_seconds < 3 OR fall_time_seconds IS NULL);
